rules.definition:
CREATE RULE pg_settings_u AS
    ON UPDATE TO pg_settings
   WHERE new.name = old.name DO  SELECT set_config(old.name, new.setting, false) AS set_config;

relations.view_definition:
SELECT name,
   setting
  FROM pg_config() pg_config(name, setting);

